-- Atualiza modelos padrão do MDT para PT-BR e estrutura orientada a RP policial brasileiro
-- Mantém suporte multi-idioma: não altera chaves internas, apenas conteúdo exibido ao usuário

DELETE FROM `mdt_report_templates`
WHERE `name` IN ('Standard Incident', 'Traffic Stop', 'Use of Force');

ON DUPLICATE KEY UPDATE
`content` = VALUES(`content`),
`type` = VALUES(`type`),
`job_type` = VALUES(`job_type`),
`updated_at` = CURRENT_TIMESTAMP();
